13	// MaxInlinePromptBytes is the largest prompt we allow to be passed as a single
14	// CLI argument. This stays well below common argv limits so long transcripts
15	// fail predictably instead of hitting OS-dependent exec errors.
16	const MaxInlinePromptBytes = 64 * 1024
17	
18	// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
19	type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
20	
21	// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
22	// directory with all GIT_* environment variables removed. This avoids recursive
23	// hook triggers and repo side effects while preserving provider-specific flags.
24	func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
25		if runner == nil {
26			runner = exec.CommandContext
27		}
28	
29		cmd := runner(ctx, binary, args...)
30		cmd.Dir = os.TempDir()
31		cmd.Env = StripGitEnv(os.Environ())
32		if stdin != "" {
33			cmd.Stdin = strings.NewReader(stdin)
34		}
35	
36		var stdout, stderr bytes.Buffer
37		cmd.Stdout = &stdout
38		cmd.Stderr = &stderr
39	
40		if err := cmd.Run(); err != nil {
41			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
42				return "", context.DeadlineExceeded
43			}
44			if errors.Is(ctx.Err(), context.Canceled) {
45				return "", context.Canceled
46			}
47			var execErr *exec.Error
48			if errors.As(err, &execErr) {
49				return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
50			}
51			var exitErr *exec.ExitError
52			if errors.As(err, &exitErr) {
53				detail := strings.TrimSpace(stderr.String())
54				if detail == "" {
55					detail = strings.TrimSpace(stdout.String())
56				}
57				if detail == "" {
58					detail = err.Error()
59				}
60				return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
61			}
62			return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
63		}
64	
65		result := strings.TrimSpace(stdout.String())
66		if result == "" {
67			return "", fmt.Errorf("%s CLI returned empty output", displayName)
68		}
69		return result, nil
70	}
