17	// directory with all GIT_* environment variables removed. This avoids recursive
18	// hook triggers and repo side effects while preserving provider-specific flags.
19	func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
20		if runner == nil {
21			runner = exec.CommandContext
22		}
23	
24		cmd := runner(ctx, binary, args...)
25		cmd.Dir = os.TempDir()
26		cmd.Env = StripGitEnv(os.Environ())
27		if stdin != "" {
28			cmd.Stdin = strings.NewReader(stdin)
29		}
30	
31		var stdout, stderr bytes.Buffer
32		cmd.Stdout = &stdout
33		cmd.Stderr = &stderr
34	
35		if err := cmd.Run(); err != nil {
36			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
37				return "", context.DeadlineExceeded
38			}
39			if errors.Is(ctx.Err(), context.Canceled) {
40				return "", context.Canceled
41			}
42			var execErr *exec.Error
43			if errors.As(err, &execErr) {
44				return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
45			}
46			var exitErr *exec.ExitError
47			if errors.As(err, &exitErr) {
48				detail := strings.TrimSpace(stderr.String())
49				if detail == "" {
50					detail = strings.TrimSpace(stdout.String())
51				}
52				if detail == "" {
53					detail = err.Error()
54				}
55				return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
56			}
57			return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
58		}
59	
60		result := strings.TrimSpace(stdout.String())
61		if result == "" {
62			return "", fmt.Errorf("%s CLI returned empty output", displayName)
63		}
64		return result, nil
65	}
66	
67	func StripGitEnv(env []string) []string {
68		filtered := make([]string, 0, len(env))
69		for _, e := range env {
70			if !strings.HasPrefix(e, "GIT_") {
71				filtered = append(filtered, e)
72			}
73		}
74		return filtered
75	}
